#!/usr/bin/env python3
"""
Build the Round 1 submission PDF for PrismCheck AI (A2Z Creators).
Light, airy visual theme: white background, pastel fills, soft teal/amber/green accents.
Diagrams are drawn as vectors so they stay crisp at any zoom.
"""
import json
import os
from fpdf import FPDF
import figures

HERE = os.path.dirname(os.path.abspath(__file__))
# Static instances of the Ubuntu variable font, generated by setup_fonts.py.
# The distro's Ubuntu-R/B/M files are symlinks to one variable font, so fpdf2
# would render every weight at 400 and bold headings would silently vanish.
FONT_DIR = os.path.join(HERE, "fonts")
FR = os.path.join(FONT_DIR, "Ubuntu-Regular.ttf")
FB = os.path.join(FONT_DIR, "Ubuntu-Bold.ttf")
FO = os.path.join(FONT_DIR, "Ubuntu-Italic.ttf")
FBI = os.path.join(FONT_DIR, "Ubuntu-BoldItalic.ttf")
FM = os.path.join(FONT_DIR, "Ubuntu-Medium.ttf")
TOC_CACHE = os.path.join(HERE, "_toc.json")

# ---- palette (all light / mid tones, no dark blocks) ----
INK = (62, 74, 80)
MUTED = (112, 126, 134)
TEAL = (46, 138, 153)
TEALD = (34, 112, 126)
TEALF = (233, 246, 248)
AMBER = (206, 145, 72)
AMBERF = (253, 244, 230)
GREEN = (74, 150, 122)
GREENF = (232, 246, 240)
ROSE = (188, 104, 120)
ROSEF = (252, 238, 241)
LINE = (222, 232, 236)
WHITE = (255, 255, 255)
COVER = (246, 251, 252)
CREAM = (253, 252, 249)

M = 16.0
W = 210.0
H = 297.0
CW = W - 2 * M
BOT = H - 20

P = dict(ink=INK, muted=MUTED, teal=TEAL, teald=TEALD, tealf=TEALF,
         amber=AMBER, amberf=AMBERF, green=GREEN, greenf=GREENF,
         rose=ROSE, rosef=ROSEF, line=LINE, white=WHITE)


class Doc(FPDF):
    def __init__(self, *a, **kw):
        super().__init__(*a, **kw)
        self.current_section = "Overview"
        self.toc_entries = []

    def header(self):
        if self.page_no() == 1:
            return
        self.set_draw_color(*LINE)
        self.set_line_width(0.4)
        self.line(M, 13.8, W - M, 13.8)
        self.set_font("UB", "", 7.3)
        self.set_text_color(*MUTED)
        self.set_xy(M, 8.8)
        self.cell(96, 4, "PRISMCHECK AI  \u00b7  ROUND 1: THE PLAN")
        self.set_xy(W - M - 96, 8.8)
        head = self.current_section
        if len(head) > 54:
            head = head[:54].rsplit(" ", 1)[0].rstrip(" ,:;") + "\u2026"
        self.cell(96, 4, head.upper(), align="R")
        # fpdf keeps whatever position the header leaves behind; restore it
        self.set_xy(self.l_margin, self.t_margin)

    def footer(self):
        if self.page_no() == 1:
            return
        self.set_draw_color(*LINE)
        self.set_line_width(0.3)
        self.line(M, H - 15.5, W - M, H - 15.5)
        self.set_font("UB", "", 7.3)
        self.set_text_color(*MUTED)
        self.set_xy(M, H - 13.6)
        self.cell(W - 2 * M, 5, "Page " + str(self.page_no()) + " of {nb}", align="C")


def new_doc():
    pdf = Doc(orientation="P", unit="mm", format="A4")
    pdf.set_compression(True)
    pdf.add_font("UB", "", FR)
    pdf.add_font("UB", "B", FB)
    pdf.add_font("UB", "I", FO)
    pdf.add_font("UB", "BI", FBI)
    pdf.alias_nb_pages()
    pdf.set_auto_page_break(True, 21)
    pdf.set_margins(M, 20, M)
    pdf.set_title("PrismCheck AI - Round 1: The Plan - Team A2Z Creators")
    pdf.set_author("A2Z Creators")
    pdf.set_subject("Brand compliance review, explained and cited")
    return pdf


def measure(pdf, text, w, size, lh, style=""):
    pdf.set_font("UB", style, size)
    try:
        return pdf.multi_cell(w, lh, text, dry_run=True, output="HEIGHT")
    except Exception:
        return lh * max(1, int(len(text) / max(8, w * 1.7)) + 1)


def ensure(pdf, h):
    if pdf.get_y() + h > BOT:
        pdf.add_page()


def para(pdf, text, x=M, w=CW, size=10.3, lh=5.8, color=INK, bold=False, italic=False):
    style = "B" if bold else ("I" if italic else "")
    pdf.set_font("UB", style, size)
    pdf.set_text_color(*color)
    # full-width prose: never split a short paragraph, never leave a 1-2 line widow
    if x == M and w == CW:
        total = measure(pdf, text, w, size, lh, style=style)
        avail = BOT - pdf.get_y()
        if total > avail and avail > lh:
            lines = max(1, round(total / lh))
            fits = int(avail // lh)
            if lines <= 6 or lines - fits <= 2:
                pdf.add_page()
    pdf.set_x(x)
    pdf.multi_cell(w, lh, text)
    pdf.set_x(M)


def bullets(pdf, items, x=M, w=CW, size=9.9, lh=5.7, gap=1.2, dot=TEAL, color=INK):
    for it in items:
        hh = measure(pdf, it, w - 6, size, lh)
        ensure(pdf, hh + gap)
        y = pdf.get_y()
        pdf.set_fill_color(*dot)
        pdf.rect(x + 1.2, y + 1.9, 1.5, 1.5, style="F")
        pdf.set_font("UB", "", size)
        pdf.set_text_color(*color)
        pdf.set_xy(x + 6, y)
        pdf.multi_cell(w - 6, lh, it)
        pdf.set_x(M)
        pdf.ln(gap)


def section(pdf, num, title, kicker=""):
    need = 24 if not kicker else 30
    # set the running head before any page break so the new page's header is right
    pdf.current_section = str(num) + ". " + title
    ensure(pdf, need)
    if pdf.get_y() > 30:
        pdf.ln(2.5)
    y = pdf.get_y()
    pdf.set_fill_color(*TEAL)
    pdf.rect(M, y, 8.6, 8.6, style="F")
    pdf.set_font("UB", "B", 10.5)
    pdf.set_text_color(*WHITE)
    pdf.set_xy(M, y + 1.1)
    pdf.cell(8.6, 6.4, str(num), align="C")

    pdf.set_font("UB", "B", 16.2)
    pdf.set_text_color(*TEALD)
    pdf.set_xy(M + 11.5, y - 0.4)
    pdf.cell(0, 9, title)

    pdf.set_draw_color(*LINE)
    pdf.set_line_width(0.4)
    pdf.line(M, y + 11.2, W - M, y + 11.2)
    pdf.set_y(y + 14.5)
    _label = str(num) + ". " + title
    level = 1 if any(c.isalpha() for c in str(num)) else 0
    pdf.start_section(_label, level=level)
    if not any(_e[0] == _label for _e in pdf.toc_entries):
        pdf.toc_entries.append((_label, pdf.page_no()))

    if kicker:
        para(pdf, kicker, size=10.0, lh=5.1, color=MUTED, italic=True)
        pdf.ln(0.6)


def subhead(pdf, text, color=TEALD, size=11.8, space=2.4):
    ensure(pdf, 14)
    pdf.ln(space)
    pdf.set_font("UB", "B", size)
    pdf.set_text_color(*color)
    pdf.set_x(M)
    pdf.multi_cell(CW, 6.2, text)
    pdf.set_x(M)
    pdf.ln(0.8)


def card(pdf, x, y, w, h, fill, border=None, radius=None):
    pdf.set_fill_color(*fill)
    if border:
        pdf.set_draw_color(*border)
        pdf.set_line_width(0.4)
        pdf.rect(x, y, w, h, style="DF")
    else:
        pdf.rect(x, y, w, h, style="F")


def stat_row(pdf, stats, fill=TEALF, accent=TEALD):
    """stats: list of (big, label, sub)"""
    n = len(stats)
    gap = 3.2
    cw = (CW - gap * (n - 1)) / n
    lab_h = max(measure(pdf, s[1], cw - 6, 8.2, 3.6, style="B") for s in stats)
    sub_h = max(measure(pdf, s[2], cw - 6, 7.2, 3.2) for s in stats if s[2])
    h = 10.4 + lab_h + sub_h + 3.2
    ensure(pdf, h + 3)
    y = pdf.get_y()
    for i, (big, label, sub) in enumerate(stats):
        x = M + i * (cw + gap)
        card(pdf, x, y, cw, h, fill, LINE)
        pdf.set_font("UB", "B", 15)
        pdf.set_text_color(*accent)
        pdf.set_xy(x + 3, y + 2.6)
        pdf.cell(cw - 6, 7, big)
        pdf.set_font("UB", "B", 8.2)
        pdf.set_text_color(*INK)
        pdf.set_xy(x + 3, y + 10.4)
        pdf.multi_cell(cw - 6, 3.6, label)
        if sub:
            pdf.set_font("UB", "", 7.2)
            pdf.set_text_color(*MUTED)
            pdf.set_xy(x + 3, y + 10.4 + lab_h + 0.9)
            pdf.multi_cell(cw - 6, 3.2, sub)
    pdf.set_y(y + h + 3)


def kv_table(pdf, rows, label_w=50, fill_a=WHITE, fill_b=(250, 253, 254), size=10.0):
    """rows: list of (label, text). Alternating light rows, safe variable height."""
    for i, (label, text) in enumerate(rows):
        inner = CW - label_w - 8
        body_h = measure(pdf, text, inner, size, 4.6)
        label_h = measure(pdf, label, label_w, 9.3, 4.4, style="B")
        hh = max(body_h, label_h, 6)
        row_h = hh + 5.2
        ensure(pdf, row_h)
        y = pdf.get_y()
        card(pdf, M, y, CW, row_h, fill_a if i % 2 == 0 else fill_b, LINE)
        pdf.set_font("UB", "B", 9.3)
        pdf.set_text_color(*TEALD)
        pdf.set_xy(M + 3.4, y + 2.6)
        pdf.multi_cell(label_w, 4.4, label)
        pdf.set_font("UB", "", size)
        pdf.set_text_color(*INK)
        pdf.set_xy(M + label_w + 4.6, y + 2.6)
        pdf.multi_cell(inner, 4.6, text)
        pdf.set_x(M)
        pdf.set_y(y + row_h)
    pdf.ln(1)


def pill(pdf, x, y, text, fill, accent, size=7.2):
    pdf.set_font("UB", "B", size)
    w = pdf.get_string_width(text) + 5.5
    pdf.set_fill_color(*fill)
    pdf.rect(x, y, w, 5.2, style="F")
    pdf.set_text_color(*accent)
    pdf.set_xy(x + 2.6, y + 1.0)
    pdf.cell(w - 4, 3.4, text)
    return x + w


