    pdf.set_font("UB", "", 9.4)
    pdf.set_text_color(*INK)
    pdf.multi_cell(CW * 0.62, 5.0,
        "A review gate that sits between \u201csomeone made this\u201d and \u201cthis goes live\u201d, "
        "checking content against one approved Brand Kit and explaining every flag with a citation.")

    # team block on cover
    y0 = 132
    card(pdf, M, y0, CW, 34, WHITE, LINE)
    pdf.set_font("UB", "B", 8.2)
    pdf.set_text_color(*TEALD)
    pdf.set_xy(M + 5, y0 + 4)
    pdf.cell(0, 4, "TEAM A2Z CREATORS")
    pdf.set_font("UB", "", 9.0)
    pdf.set_text_color(*INK)
    pdf.set_xy(M + 5, y0 + 10.5)
    pdf.multi_cell(CW - 10, 5.0,
        "Venkata Narayana G V  \u2014  Team Leader, Developer  \u2014  venkatnarayana727@gmail.com")
    pdf.set_x(M + 5)
    pdf.multi_cell(CW - 10, 5.0,
        "Mahesh Babu Ch  \u2014  Research and Analysis  \u2014  maheshmamtha242@gmail.com")

    # at-a-glance strip
    stats = [
        ("3", "content formats\nreviewed", "text \u00b7 image \u00b7 document"),
        ("4", "cited checks per\nsubmission", "claims \u00b7 tone \u00b7 visual \u00b7 access"),
        ("100%", "of flags require\nan approved source", "citation or silence"),
        ("0", "automatic\noverrides", "human decision is final"),
    ]
    pdf.set_y(176)
    stat_row(pdf, [(a, b, c) for a, b, c in stats])

    # footnote
    pdf.set_y(232)
