# ---------------------------------------------------------------- page 2: snapshot
def snapshot(pdf):
    pdf.add_page()
    section(pdf, "0", "The one-page verdict",
            kicker="Read this page if you read nothing else. The rest of the document is the evidence.")

    # problem | answer | difference  (3 stacked blocks)
    blocks = [
        ("THE PROBLEM, IN ONE LINE",
         "Organisations do not fail to govern their brand because they lack guidelines. "
         "They fail because the brand book is not the system of record at the moment content is published.",
         ROSE, ROSEF),
        ("OUR ANSWER, IN ONE LINE",
         "PrismCheck reviews text, images and documents against one approved Brand Kit before publication, "
         "explains every finding with a citation, and suggests fixes that keep the creator's intent.",
         TEAL, TEALF),
        ("WHY IT IS DIFFERENT",
         "Other tools ask whether content feels off-brand. PrismCheck asks for the kit line: no source, no flag. "
         "And when humans repeatedly override a rule, it treats the rule, not the person, as the suspect.",
         GREEN, GREENF),
    ]
    for label, text, accent, fill in blocks:
        hh = measure(pdf, text, CW - 12, 9.6, 5.0) + 13
        ensure(pdf, hh + 2)
        y = pdf.get_y()
        card(pdf, M, y, CW, hh, fill, None)
        pdf.set_fill_color(*accent)
        pdf.rect(M, y, 2.6, hh, style="F")
        pdf.set_font("UB", "B", 7.6)
        pdf.set_text_color(*accent)
        pdf.set_xy(M + 6, y + 3.2)
        pdf.cell(0, 4, label)
        pdf.set_font("UB", "", 9.6)
        pdf.set_text_color(*INK)
        pdf.set_xy(M + 6, y + 8.4)
        pdf.multi_cell(CW - 12, 5.0, text)
        pdf.set_x(M)
        pdf.set_y(y + hh + 3.0)

    subhead(pdf, "How this document scores against the Round 1 rubric")
    rows = [
        ("25 pts \u00b7 Understanding", "Section 1 defines the failure modes line by line, names the exact gap we solve, and backs it with sourced evidence and a concrete organisational setting."),
        ("25 pts \u00b7 Solution", "Section 3 and 4 give a named, step-by-step walkthrough of one real submission, so a judge can see a person using the product, not just a feature list."),
        ("20 pts \u00b7 Technical plan", "Section 6 justifies every layer of the stack, names the hardest problem (an LLM that invents issues), and shows the architecture that prevents it."),
        ("15 pts \u00b7 Originality", "Section 3 states three mechanisms no other team is likely to have: Citation Lock, Intent Lock and Guideline Health."),
        ("15 pts \u00b7 Feasibility", "Section 8 commits to a deliberately small Round 2 build, deterministic checks first, with everything else explicitly deferred."),
    ]
    kv_table(pdf, rows, label_w=42, size=9.9)

    pdf.ln(1)
    para(pdf, "Sections follow the required submission order exactly: 1 Understanding \u00b7 2 Users \u00b7 "
              "3 Solution \u00b7 4 Workflow \u00b7 5 Features \u00b7 6 Technology \u00b7 7 Responsibilities \u00b7 "
              "8 Development plan \u00b7 9 Impact \u00b7 10 Future scope \u00b7 11 Team details.",
         size=8.0, lh=4.9, color=MUTED, italic=True)


# ---------------------------------------------------------------- 1 understanding
def sec1(pdf):
    pdf.add_page()
    section(pdf, 1, "Understanding of the given problem statement",
            kicker="What the brief actually asks, who feels it, and the specific slice we take responsibility for.")

    para(pdf, "The brief is not a request for a brand checker. Growing organisations now publish through "
              "multiple employees, external agencies and AI tools, and none of them sit inside the central brand "
              "team. So the brief asks for something narrower and harder: a system that keeps a single approved "
              "source of truth in force at the exact moment content is published, by people and tools the brand "
              "team does not control.")
    pdf.ln(1)

    subhead(pdf, "Four failure modes named in the brief, and what each one costs")
    items = [
        ("Incorrect claims and unsupported promotional promises",
         "A creator or an AI tool invents a specification, price or guarantee that no approved source supports. "
         "The cost is legal and regulatory exposure, and the damage lands before anyone notices."),
        ("Outdated information and inconsistent language",
         "Approved guidelines live in documents and folders that nobody opens at publish time, so last quarter's "
         "wording and last year's offer keep circulating."),
        ("Off-brand visuals and inconsistent asset use",
         "Colour drift, unapproved logo handling and wrong typography are usually caught late, subjectively, "
         "or not at all, because visual checks are manual."),
        ("Accessibility failures",
         "Low contrast and missing alternative text reach the audience, creating reputational and compliance risk "
         "that automated review could have caught deterministically."),
    ]
    for title, body in items:
        hh = measure(pdf, body, CW - 13, 8.8, 4.7) + 12
        ensure(pdf, hh + 2)
        y = pdf.get_y()
        card(pdf, M, y, CW, hh, WHITE, LINE)
        pdf.set_fill_color(*TEAL)
        pdf.rect(M, y, 2.2, hh, style="F")
        pdf.set_font("UB", "B", 9.2)
        pdf.set_text_color(*TEALD)
        pdf.set_xy(M + 6, y + 3.0)
        pdf.multi_cell(CW - 13, 4.6, title)
        pdf.set_font("UB", "", 8.8)
        pdf.set_text_color(*INK)
        pdf.set_xy(M + 6, y + 8.2)
        pdf.multi_cell(CW - 13, 4.7, body)
        pdf.set_x(M)
        pdf.set_y(y + hh + 2.4)

    para(pdf, "Those failures map onto six detection areas the brief names explicitly: tone, terminology, "
              "messaging, visual consistency, accessibility and unsupported promotional claims. Each is a separate "
              "check in Section 5, and each must cite the kit item it tested against.",
         size=10.0, lh=5.5, color=INK)

    subhead(pdf, "The gap we take responsibility for")
    y = pdf.get_y()
    card(pdf, M, y, CW, 17, AMBERF, None)
    pdf.set_fill_color(*AMBER)
    pdf.rect(M, y, 2.6, 17, style="F")
    pdf.set_font("UB", "B", 9.4)
    pdf.set_text_color(*AMBER)
    pdf.set_xy(M + 6, y + 2.6)
    pdf.cell(0, 4.6, "One gate, one source of truth, one citation behind every finding.")
    pdf.set_font("UB", "", 9.0)
    pdf.set_text_color(*INK)
    pdf.set_xy(M + 6, y + 8.0)
    pdf.multi_cell(CW - 12, 4.8,
        "We do not generate content, and we do not replace the brand team. We make the approved Brand Kit "
        "the only admissible evidence in the last review before publish.")
    pdf.set_x(M)
    pdf.set_y(y + 20)

    subhead(pdf, "Evidence that the problem is real")
    stats = [
        ("81%", "of companies still deal with off-brand content", "Lucidpress/Marq, 2019 \u00b7 primary survey, n=200+"),
        ("33%", "upper-bound revenue lift from consistent branding", "Lucidpress/Marq, 2019 \u00b7 23% in 2016"),
        ("50%", "of organisations created more content than the year before", "Lucidpress/Marq, 2019 \u00b7 primary"),
        ("7\u201310 days", "typical pre-governance approval cycle", "Typeface, 2026 \u00b7 practitioner guidance"),
    ]
    stat_row(pdf, stats, fill=AMBERF, accent=AMBER)
    pdf.ln(1)
    para(pdf, "How to read our evidence. Lucidpress/Marq (2019, n=200+) is primary research; Typeface, "
              "Aprimo and CrawlQ are labelled practitioner guidance, not research; WCAG 2.2 SC 1.4.3 and "
              "EU AI Act Article 50 are cited as specifications. We dropped stat-roundup figures we could "
              "not trace to a primary source: a plan is only as credible as its weakest citation.",
         size=8.4, lh=5.2, color=MUTED, italic=True)


    # ---- explanatory figures (Section 1) ----
    pdf.add_page()
    subhead(pdf, "The problem and the fix, in two pictures", space=0)
    figures.draw_drift(pdf, M, CW, P)
    para(pdf, "Figure 1 \u2014 Without a gate, the same three sources publish straight to the audience, and four "
              "kinds of error reach customers before anyone notices. With the gate, every draft is compared "
              "with the approved Brand Kit first, and nothing is flagged without a cited source.",
         size=7.8, lh=4.8, color=MUTED, italic=True)
    pdf.ln(2)
    figures.draw_kit_and_checks(pdf, M, CW, P)
    para(pdf, "Figure 2 \u2014 The kit is small and structured on purpose: four kinds of approved material feed "
              "four checks. The checks that must never guess - terminology, colour distance and contrast - run "
              "deterministically, and the model only proposes a citation and a rewrite.",
         size=7.8, lh=4.8, color=MUTED, italic=True)


# ---------------------------------------------------------------- 2 users
def sec2(pdf):
    pdf.add_page()
    section(pdf, 2, "The users affected by the problem",
            kicker="Three people feel this daily. Their needs drive the workflow in Section 4.")

    people = [
        ("Content creator / copywriter",
         "Needs to ship fast without guessing.",
         "Waits days for approval, gets subjective pushback with no citation, and learns the rule only after breaking it.",
         "\u201cI guess the tone and hope the manager doesn't catch it after the deadline.\u201d",
         TEAL, TEALF),
        ("Brand / compliance manager",
         "Needs to catch problems before they are live.",
         "Spends review time on the same low-level errors, and usually sees the asset after it has already gone out.",
         "\u201cI keep seeing the same mistakes on things that go live before I review them.\u201d",
         AMBER, AMBERF),
        ("Agency / freelance contributor",
         "Needs to know which source is current.",
         "Works across several clients, each with a different brand document, and cannot tell which version is authoritative.",
         "\u201cEvery client sends a different brand PDF, and I never know which one is current.\u201d",
         GREEN, GREENF),
    ]
    for role, need, pain, quote, accent, fill in people:
        hh = 34
        ensure(pdf, hh + 3)
        y = pdf.get_y()
