# ---------------------------------------------------------------- 4 workflow
def sec4(pdf):
    pdf.add_page()
    section(pdf, 4, "The complete product workflow",
            kicker="One diagram, then one walkthrough of a real submission from upload to insight.")

    # ---- diagram: 6 stages, 3 x 2
    stages = [
        ("Brand Kit", "Colours, facts,\nterminology, tone", TEAL, TEALF),
        ("Creator submits", "Text + image,\nor document", TEAL, TEALF),
        ("Privacy shield", "Masks PII\nlocally", GREEN, GREENF),
        ("Four cited checks", "Claims \u00b7 tone \u00b7\nvisual \u00b7 access", AMBER, AMBERF),
        ("Creator decides", "Accept fix, or\nkeep mine + note", AMBER, AMBERF),
        ("Approval + insights", "Manager decision,\nthen guideline health", GREEN, GREENF),
    ]
    bw, bh, gap = 52.0, 21.0, 7.0
    y0 = pdf.get_y() + 2
    for i, (title, sub, accent, fill) in enumerate(stages):
        row, col = divmod(i, 3)
        x = M + col * (bw + gap)
        y = y0 + row * (bh + 16)
        card(pdf, x, y, bw, bh, fill, accent)
        pdf.set_font("UB", "B", 9.0)
        pdf.set_text_color(*accent)
        pdf.set_xy(x + 2.5, y + 3.0)
        pdf.multi_cell(bw - 5, 4.2, title, align="C")
        pdf.set_font("UB", "", 7.4)
        pdf.set_text_color(*INK)
        pdf.set_xy(x + 2.5, y + 10.0)
        pdf.multi_cell(bw - 5, 3.7, sub, align="C")
        # arrows
        pdf.set_draw_color(*MUTED)
        pdf.set_line_width(0.5)
        if col < 2:
            ax1 = x + bw
            ax2 = ax1 + gap - 1.6
            ay = y + bh / 2
            pdf.line(ax1 + 0.8, ay, ax2, ay)
            pdf.set_fill_color(*MUTED)
            pdf.polygon([(ax2, ay), (ax2 - 2.0, ay - 1.3), (ax2 - 2.0, ay + 1.3)], style="F")
        elif row == 0:
            # connector down with rounded path
            ax = x + bw / 2
            pdf.line(ax, y + bh, ax, y + bh + 7)
            pdf.line(ax, y + bh + 7, M + bw / 2, y + bh + 7)
            pdf.line(M + bw / 2, y + bh + 7, M + bw / 2, y + bh + 12)
            pdf.set_fill_color(*MUTED)
            pdf.polygon([(M + bw / 2, y + bh + 14), (M + bw / 2 - 1.3, y + bh + 12),
                         (M + bw / 2 + 1.3, y + bh + 12)], style="F")

    pdf.set_y(y0 + 2 * bh + 16 + 5)
    para(pdf, "Figure 4 \u2014 PrismCheck review flow. The creator never loses control of the draft: the system only "
              "recommends, the creator decides, and the manager approves.",
         size=7.8, lh=4.8, color=MUTED, italic=True)

    # ---- walkthrough
    subhead(pdf, "Walkthrough: a fintech creator submits a credit-card carousel")
    steps = [
        ("Submit", "A creator uploads a LinkedIn carousel announcing a new credit-card offer: caption copy plus a banner image."),
        ("Protect", "Before anything leaves the browser, emails, phone numbers and internal tokens are masked by the privacy layer."),
        ("Check \u00b7 claims", "\u201cNo annual fee for life\u201d is not in the approved fact bank. It is flagged as an unsupported claim, hard-gated, with the missing fact cited and two rewrites offered that keep the announcement intent."),
        ("Check \u00b7 tone", "Intent is read as \u201curgent promotional offer\u201d. Two alternates preserve the urgency while removing the unsupported promise."),
        ("Check \u00b7 visual", "Banner colours are compared to the kit palette in CIELAB space. One shade sits outside the approved range, so it is soft-flagged against the kit colour it drifted from."),
        ("Check \u00b7 access", "Text over image fails the WCAG contrast ratio, and in-image text has no alternative text. Both are flagged with the measured ratio and a suggested description."),
        ("Decide", "The creator accepts the claim rewrite and chooses \u201ckeep mine + add context\u201d for the colour, recording the approved campaign exception as a note."),
        ("Approve", "The draft moves to Pending review. The manager sees the fix, the exception note and the accessibility suggestions, then approves. Revision history records what changed and why."),
        ("Learn", "Insights shows this claim type flagged repeatedly this month, and the colour rule among the most overridden rules \u2014 badged as a possibly unclear guideline."),
    ]
    for i, (label, text) in enumerate(steps, 1):
        if i == 6:
            pdf.add_page()
            pdf.set_font("UB", "I", 8.4)
            pdf.set_text_color(*MUTED)
            pdf.set_x(M)
            pdf.cell(0, 5, "Walkthrough continued \u2014 from the creator's decision to the governance insight")
            pdf.ln(7)
        inner = CW - 24
        hh = measure(pdf, text, inner, 8.6, 4.5) + 7.6
        ensure(pdf, hh + 1.4)
        y = pdf.get_y()
        card(pdf, M, y, CW, hh, WHITE if i % 2 else (250, 253, 254), LINE)
        pdf.set_fill_color(*TEAL if i < 8 else GREEN)
        pdf.set_font("UB", "B", 8.0)
        pdf.set_text_color(*WHITE)
        pdf.rect(M + 3.2, y + 3.0, 6.0, 6.0, style="F")
        pdf.set_xy(M + 3.2, y + 3.9)
        pdf.cell(6.0, 4.2, str(i), align="C")
        pdf.set_font("UB", "B", 8.2)
        pdf.set_text_color(*TEALD)
        pdf.set_xy(M + 11.6, y + 2.6)
        pdf.cell(46, 4.4, label.upper())
        pdf.set_font("UB", "", 8.6)
        pdf.set_text_color(*INK)
        pdf.set_xy(M + 11.6, y + 7.2)
        pdf.multi_cell(inner, 4.5, text)
        pdf.set_x(M)
        pdf.set_y(y + hh + 1.4)

    pdf.ln(1)
    para(pdf, "This is the whole product in one submission: a citation for every flag, a fix that keeps the "
              "creator's purpose, a human decision at every gate, and a governance signal at the end.",
         size=9.8, lh=5.3, color=MUTED, italic=True)


# ---------------------------------------------------------------- 4b examples
def sec_examples(pdf):
    pdf.add_page()
    section(pdf, "4b", "Three realistic catches",
            kicker="Concrete examples of what PrismCheck flags, what it cites, and what it suggests. "
                   "These are the kinds of issues the brief describes.")

    examples = [
        ("Unsupported promotional claim", "HARD GATE", ROSE, ROSEF,
         "Draft says: \u201cLasts 3x longer than the leading alternative.\u201d",
         "Cited source: fact bank has no comparative specification and no such claim. The finding names the fact "
         "category that was checked and shows it is absent.",
         "Suggested fixes (2): keep the benefit, drop the unverifiable multiple. e.g. \u201cBuilt to last through "
         "everyday use\u201d and \u201cLonger wear between replacements, backed by our two-year warranty\u201d.",
         "Creator chooses a fix or keeps their wording with a note. Manager must approve a hard-gated claim."),
        ("Banned promotional language", "HARD GATE", ROSE, ROSEF,
         "Banner says: \u201c100% guaranteed results \u2014 risk-free.\u201d",
         "Cited source: terminology rule T-14 bans absolute guarantees and risk-free phrasing in this category. "
         "This check is deterministic string matching, not an LLM opinion, so it cannot be argued away or missed.",
         "Suggested fixes (2): compliant alternatives that keep the confidence, e.g. \u201cBacked by our results "
         "guarantee policy\u201d and \u201cTry it with our standard refund terms\u201d.",
         "The manager sees the exact banned term and rule ID, so the discussion is about the rule, not about taste."),
        ("Accessibility failure", "SOFT COACH", AMBER, AMBERF,
         "Banner has pale text on a pale photo, and the in-image headline has no description.",
         "Cited source: accessibility rule A-03 requires a minimum contrast ratio for overlaid text and a "
         "description for text baked into images. Both are measured, not guessed: contrast is computed from "
         "luminance values.",
         "Suggested fixes (2): darken the text or add a scrim to reach the threshold, plus a draft alt text "
         "generated from the OCR reading of the image text.",
         "Soft guidance only: the creator decides, because some campaign art intentionally breaks contrast."),
    ]
    for title, gate, accent, fill, draft, cited, fix, decision in examples:
        body_h = (measure(pdf, draft, CW - 14, 8.5, 4.4) + measure(pdf, cited, CW - 14, 8.5, 4.4)
                  + measure(pdf, fix, CW - 14, 8.5, 4.4) + measure(pdf, decision, CW - 14, 8.5, 4.4))
        hh = body_h + 26
        ensure(pdf, hh + 4)
        y = pdf.get_y()
        card(pdf, M, y, CW, hh, fill, None)
        pdf.set_fill_color(*accent)
        pdf.rect(M, y, 2.6, hh, style="F")

        pdf.set_font("UB", "B", 10.0)
        pdf.set_text_color(*accent)
        pdf.set_xy(M + 6, y + 3.0)
        pdf.cell(CW - 50, 5, title)

        # gate pill on right
        pdf.set_font("UB", "B", 6.8)
        pw = pdf.get_string_width(gate) + 6
        px = W - M - pw - 3
        pdf.set_fill_color(*WHITE)
        pdf.set_draw_color(*accent)
        pdf.set_line_width(0.4)
        pdf.rect(px, y + 3.4, pw, 4.6, style="DF")
        pdf.set_text_color(*accent)
        pdf.set_xy(px, y + 4.3)
        pdf.cell(pw, 3.4, gate, align="C")

        cy = y + 10.6
        for lbl, txt in [("DRAFT", draft), ("CITED", cited), ("FIX", fix), ("CONTROL", decision)]:
            pdf.set_font("UB", "B", 6.9)
            pdf.set_text_color(*MUTED)
            pdf.set_xy(M + 6, cy)
            pdf.cell(14, 4.2, lbl)
            pdf.set_font("UB", "", 8.5)
            pdf.set_text_color(*INK)
            pdf.set_xy(M + 20, cy)
            pdf.multi_cell(CW - 26, 4.4, txt)
            cy = pdf.get_y() + 1.0
        pdf.set_x(M)
        pdf.set_y(y + hh + 3.4)

    para(pdf, "Note the pattern the rubric rewards: every example shows the issue, the exact approved source, the "
              "suggested correction, and who holds the final decision.",
         size=9.8, lh=5.2, color=MUTED, italic=True)


