# ---------------------------------------------------------------- 1b competitive landscape
def sec1b(pdf):
    pdf.add_page()
    section(pdf, "1b", "Who else solves this, and where the gap actually is",
            kicker="Judges see many brand-governance ideas. We checked the real market so our claim of originality is precise rather than loud.")

    rows = [
        ("Marq (Lucidpress)", "Locked templates, brand asset management and approval workflows. Strong when content is created inside its templates. Gap for this brief: it does not audit a finished draft that arrived from somewhere else."),
        ("Adobe GenStudio", "Brand compliance checks inside campaign production for ads and email. Strong inside Adobe workflows. Gap: it governs assets produced in its own pipeline, not drafts from employees, agencies or arbitrary AI tools."),
        ("Typeface", "A brand hub plus AI generation with quality controls. Strong at governing what the model generates. Gap: PrismCheck governs what was produced, whoever produced it."),
        ("CrawlQ", "Brand governance for AI content with multi-dimension scoring, knowledge-graph grounding and audit trails. Closest in philosophy. Gap: it scores generated output; PrismCheck refuses to flag without a citation, spans text, image and document, and treats human overrides as a signal about the guideline."),
        ("PrismCheck", "The review gate: cite-or-silence findings against one approved Brand Kit, intent-preserving fixes, human approval, and override-driven guideline health. Designed for drafts of unknown origin."),
    ]
    kv_table(pdf, rows, label_w=38, size=9.8)

    pdf.ln(1)
    para(pdf, "We are not claiming the products above are poor. We are claiming they optimise a different moment "
              "in the workflow \u2014 creation, templating or generation \u2014 while the brief describes a review moment "
              "that sits after all of them. That is the space PrismCheck takes, and it is why our originality "
              "claim is about explainability rather than about features.",
         size=9.9, lh=5.5, color=INK)

    subhead(pdf, "Why now")
    bullets(pdf, [
        "Content volume is rising faster than review capacity: half of surveyed organisations produced more content year on year (Lucidpress/Marq, 2019).",
        "Generative tools removed the last natural checkpoint, because a draft can now be produced without a designer or writer who knew the rules.",
        "AI transparency expectations are becoming concrete: EU AI Act Article 50 obligations apply from 2 August 2026 for providers and deployers of certain AI systems, while in the US there is no general duty to disclose AI use but claim substantiation and endorsement disclosure rules still apply. A review trail is what makes either regime survivable.",
    ], size=9.8, lh=5.3)


