    for title, accent, fill, body in cards_:
        hh = measure(pdf, body, CW - 14, 8.7, 4.7) + 15
        ensure(pdf, hh + 3)
        y = pdf.get_y()
        card(pdf, M, y, CW, hh, fill, None)
