    pdf.set_font("UB", "I", 8.8)
    pdf.set_text_color(*INK)
    pdf.set_xy(M + 5, y + 8.0)
    pdf.multi_cell(CW - 10, 4.6,
        "\u201cText analysis and alternative-text suggestions use Gemini. Colour and contrast checks run locally "
        "on your machine. No content is stored as training data. Brand kit facts marked confidential stay in "
        "this organisation.\u201d")
    pdf.set_x(M)
    pdf.set_y(y + 29)

    para(pdf, "Where the law actually stands, stated carefully. In the EU, Article 50 of the AI Act sets "
              "transparency obligations for providers and deployers of certain AI systems and applies from "
              "2 August 2026. In the US there is no general federal duty to disclose AI-generated content, but "
              "advertising claim substantiation and endorsement disclosure rules still apply to whatever is "
              "published. So PrismCheck does two different things and does not blur them: it discloses its own AI "
              "use in the interface as a trust measure, and it treats claim substantiation as a hard gate, because "
              "that is where the legal exposure actually sits.",
         size=9.8, lh=5.2, color=INK)

    pdf.add_page()
    pdf.set_font("UB", "I", 8.4)
    pdf.set_text_color(*MUTED)
    pdf.set_x(M)
    pdf.cell(0, 5, "Section 6b continued \u2014 the brief's expected outcome, clause by clause")
    pdf.ln(7)

    subhead(pdf, "What the brief expects, and where this plan delivers it", space=0)
    rows = [
        ("A functional product", "Round 2 ships a working review flow end to end: upload, four cited checks, creator decision, manager approval, revision history, insights. Round 3 hardens it."),
        ("Approved source material", "Nothing is flagged unless it resolves to an approved guideline, fact or asset in the Brand Kit. The Citation Lock enforces this in code, not in prompt wording."),
        ("Understandable findings", "Each finding shows the issue, the source ID, the quoted rule, a severity and a suggested fix \u2014 readable by a non-technical creator without a glossary."),
        ("Human review", "Every draft passes through a named reviewer before it can be marked ready. Hard-gated findings cannot be self-cleared by the creator."),
        ("Realistic workflows", "Three real formats (caption, banner image, PDF or DOCX one-pager), a worked carousel example, and approval states that mirror how brand teams already work."),
    ]
