# ---------------------------------------------------------------- 6c risks
def sec6c(pdf):
    pdf.add_page()
    section(pdf, "6c", "Risks, mitigations and a performance budget",
            kicker="What could go wrong, what we do about it, and the numbers we will be measured against.")

    rows = [
        ("The model invents an issue", "Highest risk in this category. Mitigation: Citation Lock \u2014 unsourced findings are dropped by middleware before display; terminology and colour checks are deterministic, not model-driven."),
        ("The kit is too thin to review", "The system stays silent and records the gap. Mitigation: an onboarding checklist and a \u201cchecked, no rule\u201d state so silence is visible rather than mysterious."),
        ("Accessibility false positives", "Brand art sometimes breaks contrast on purpose. Mitigation: accessibility is soft coaching only, and an override records the reason for the next reviewer."),
        ("Colour drift false positives", "Campaign palettes legitimately differ. Mitigation: a tolerance band plus per-campaign approved exceptions stored in the kit rather than argued in chat."),
        ("Document parsing fails", "A corrupted or scanned PDF should not pass silently. Mitigation: an explicit unreadable state that blocks approval and asks for a text version."),
        ("Confidential material leaks", "Mitigation: masking happens client-side before any call; confidential facts are excluded from model context; no content is retained for training."),
        ("Scope overrun in the build window", "Mitigation: deterministic checks ship first, the model path second, workflow third, insights last \u2014 with a fixed cut list if time runs short."),
    ]
    kv_table(pdf, rows, label_w=44, size=9.8)

    subhead(pdf, "Performance and cost budget, stated as targets")
    para(pdf, "We are not claiming measured numbers in Round 1. These are the targets we will validate and report "
              "in Round 2, with the measurement method named so the claim is checkable.",
         size=8.3, lh=5.1, color=MUTED, italic=True)
    pdf.ln(1)
    rows = [
        ("Deterministic checks", "Under 500 ms per image on a laptop CPU. Measured locally with timing instrumentation around the OpenCV and contrast functions."),
        ("Text review with model", "Target p50 under 5 s for a 300-word draft, hard timeout at 20 s returning partial deterministic results rather than an error page."),
        ("Model calls per review", "Budget of three: claim verification, tone and intent, rewrite generation. Measured by counting outbound calls per submission."),
        ("Cost per review", "Bounded by the three-call budget and by trimming kit context to the retrieved facts, which keeps token cost predictable at low volume."),
    ]
    kv_table(pdf, rows, label_w=44, size=9.8)


