def sec9b(pdf):
    pdf.add_page()
    section(pdf, "9b", "Success metrics and evaluation plan",
            kicker="Impact claims are only credible if the measurement is designed before the feature is built.")

    rows = [
        ("Citation coverage", "100% of displayed findings resolve to a live kit item. Enforced in code, so this is a correctness gate, not a target."),
        ("Reviewer agreement", "Target 80% or higher: the share of findings an independent reviewer marks as valid, on a labelled set of 30 real drafts."),
        ("False positive rate", "Target 10% or lower. PrismCheck is deliberately built to under-report, so this number is the proof the Citation Lock works."),
        ("Silence accuracy", "Target 90% or higher: drafts with genuinely no rule violation produce no findings. This is the test that catches over-flagging."),
        ("Time to first review", "Target a 50% reduction against the team's current manual baseline, measured as submission-to-first-substantive-comment."),
        ("Guideline actions", "At least three rules rewritten per quarter from Guideline Health signals \u2014 the measure that the product improves the kit, not just the draft."),
    ]
    kv_table(pdf, rows, label_w=44, size=9.8)

    subhead(pdf, "Evaluation protocol")
    bullets(pdf, [
        "Build a labelled set of 30 real drafts at three quality levels: clean, mildly off-brand, and contains an unsupported claim.",
        "Two independent raters mark each finding as valid or invalid; disagreements are discussed and the rubric tightened, not averaged away.",
        "Report inter-rater agreement (Cohen\u2019s kappa, target 0.6 or above) alongside the accuracy figures, so the numbers are interpretable.",
        "Run the same set against a naive \u201cask the model to check brand compliance\u201d baseline, and publish both results. If our approach does not beat the baseline, that is the finding.",
        "Test with 3\u20135 creators and at least one reviewer, and report the friction they hit rather than only the tasks they completed.",
    ], size=9.8, lh=5.2)

    pdf.add_page()
    pdf.set_font("UB", "I", 8.4)
