def contents(pdf):
    """Contents page; page numbers come from the previous build pass."""
    pdf.add_page()
    pdf.set_y(24)
    pdf.set_font("UB", "B", 16.2)
    pdf.set_text_color(*TEALD)
    pdf.set_x(M)
    pdf.cell(0, 9, "Contents")
    pdf.ln(10.5)
    para(pdf, "Eleven required sections, plus the supporting analysis that evidences each "
              "Round 1 judging criterion.",
         size=10.0, lh=5.3, color=MUTED, italic=True)
    pdf.ln(5)
    try:
        entries = json.load(open(TOC_CACHE, encoding="utf-8"))
    except Exception:
        entries = []
    if not entries:
        entries = [("- . placeholder", 0)]

    row_h = 7.6
    for entry in entries:
        label, pg = entry[0], entry[1]
        ensure(pdf, row_h + 1)
        y = pdf.get_y()
        num, _, title = label.partition(". ")
        pdf.set_font("UB", "B", 9.6)
        pdf.set_text_color(*TEAL)
        pdf.set_xy(M, y)
        pdf.cell(11, row_h, num)
        pdf.set_font("UB", "", 10.0)
        pdf.set_text_color(*INK)
        pdf.set_xy(M + 11, y)
        pdf.cell(0, row_h, title)
        tw = pdf.get_string_width(title)
        pdf.set_font("UB", "B", 9.6)
        pdf.set_text_color(*TEALD)
        num_txt = str(pg) if pg else "\u2013"
        pw = pdf.get_string_width(num_txt) + 1.5
        pdf.set_xy(W - M - pw, y)
        pdf.cell(pw, row_h, num_txt, align="R")
        # leader dots
        pdf.set_text_color(*LINE)
        pdf.set_font("UB", "", 9.0)
        x = M + 12 + tw
        stop = W - M - pw - 2
        d = 1.45
        while x + 0.6 < stop:
            pdf.set_xy(x, y + 1.1)
            pdf.cell(0.9, row_h - 2, ".", align="C")
            x += d
        pdf.set_draw_color(*LINE)
        pdf.set_line_width(0.25)
        if pg:
            pdf.line(M, y + row_h, W - M, y + row_h)
        pdf.set_y(y + row_h)

    pdf.ln(5)
    pdf.set_font("UB", "I", 8.6)
    pdf.set_text_color(*MUTED)
    pdf.set_x(M)
    pdf.multi_cell(CW, 4.6, "Sections 1b, 3b, 4b, 6b, 6c, 8b and 9b are supporting analysis: "
                             "competitor evidence, wireframes, worked examples, responsible design, "
                             "risk, named improvements and success metrics.")


def compose(pdf):
    cover(pdf)
    contents(pdf)
    snapshot(pdf)
    sec1(pdf)
    sec1b(pdf)
    sec2(pdf)
    sec3(pdf)
    sec3b(pdf)
    sec4(pdf)
    sec_examples(pdf)
    sec5(pdf)
    sec6(pdf)
    sec6b(pdf)
    sec6c(pdf)
    sec7(pdf)
    sec8(pdf)
    sec8b(pdf)
    sec9(pdf)
    sec9b(pdf)
    sec10(pdf)
    sec11(pdf)
    return pdf


def build():
    # pass 1 learns the page of every section, pass 2 prints them on the contents page
    first = compose(new_doc())
    def _order(entries):
        def key(e):
            head = str(e[0]).split(".")[0].strip()
            num = "".join(ch for ch in head if ch.isdigit()) or "0"
            tail = "".join(ch for ch in head if not ch.isdigit())
            return (int(num), tail)
        return sorted(entries, key=key)

    first.toc_entries = _order(first.toc_entries)
    with open(TOC_CACHE, "w", encoding="utf-8") as fh:
        json.dump(first.toc_entries, fh)
    pdf = compose(new_doc())
    pdf.toc_entries = _order(pdf.toc_entries)
    if [e[1] for e in pdf.toc_entries] != [e[1] for e in first.toc_entries]:
        print("WARN contents page numbers shifted between passes")
    with open(TOC_CACHE, "w", encoding="utf-8") as fh:
        json.dump(pdf.toc_entries, fh)
    out = os.path.join(HERE, "PrismCheck_Round1_Submission.pdf")
    pdf.output(out)
    print("WROTE", out)
    print("PAGES", pdf.page_no())
    print("SECTIONS", len(pdf.toc_entries))
    return out


if __name__ == "__main__":
    build()
